import{c as r,Q as d,j as a,m as n}from"./chunks/framework.B2dUnTNU.js";const c=JSON.parse('{"title":"B42 职业排名","description":"","frontmatter":{},"headers":[],"relativePath":"b42/occupations-tier.md","filePath":"b42/occupations-tier.md","lastUpdated":1779619065000}'),e={name:"b42/occupations-tier.md"};function o(s,t,i,h,g,l){return d(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="b42-职业排名" tabindex="-1">B42 职业排名 <a class="header-anchor" href="#b42-职业排名" aria-label="Permalink to &quot;B42 职业排名&quot;">​</a></h1><p>基于 B42 当前版本的 meta，综合考虑<strong>战斗力、经济性、B42 新机制适配度</strong>做排名。重点标注 B42.16 的职业改动。</p><hr><h2 id="b42-职业变化-b42-16-更新" tabindex="-1">B42 职业变化（B42.16 更新） <a class="header-anchor" href="#b42-职业变化-b42-16-更新" aria-label="Permalink to &quot;B42 职业变化（B42.16 更新）&quot;">​</a></h2><p>在排名之前，先看和 B41 相比的关键职业变化：</p><table tabindex="0"><thead><tr><th>职业</th><th>B41 状态</th><th>B42 变化</th></tr></thead><tbody><tr><td><strong>木匠 (Carpenter)</strong></td><td>+3 Carpentry</td><td>比以前值钱——拆解不给木工 XP 了，开局高木工能让你直接造高级结构</td></tr><tr><td><strong>建筑工 (Construction Worker)</strong></td><td>+3 Short Blunt, +1 Carpentry</td><td>钝器熟练现在<strong>分开</strong>了 Short Blunt 和 Long Blunt，更精确</td></tr><tr><td><strong>护士 (Nurse)</strong></td><td>+2 First Aid, +1 Lightfooted</td><td>新增 <strong>Night Owl 特征内置</strong>（值夜班理当如此）</td></tr><tr><td><strong>老兵 (Veteran)</strong></td><td>Desensitized (免疫恐慌)</td><td>Desensitized 现在<strong>还忽略 Discomfort</strong>（不适感），Buff</td></tr><tr><td><strong>所有职业</strong></td><td>开局需 TV 练级</td><td>职业起点技能更高，<strong>不依赖早期 TV 冲级</strong></td></tr></tbody></table><h3 id="新特征-b42-16" tabindex="-1">新特征（B42.16） <a class="header-anchor" href="#新特征-b42-16" aria-label="Permalink to &quot;新特征（B42.16）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>效果</th><th>点耗</th></tr></thead><tbody><tr><td><strong>Tinkerer</strong></td><td>增加 Maintenance 技能</td><td>可选</td></tr><tr><td><strong>Target Shooter</strong></td><td>增加 Aiming 技能</td><td>可选</td></tr></tbody></table><hr><h2 id="排名总览" tabindex="-1">排名总览 <a class="header-anchor" href="#排名总览" aria-label="Permalink to &quot;排名总览&quot;">​</a></h2><h3 id="s-档-—-版本答案" tabindex="-1">S 档 — 版本答案 <a class="header-anchor" href="#s-档-—-版本答案" aria-label="Permalink to &quot;S 档 — 版本答案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>B42 适配</th></tr></thead><tbody><tr><td>🥇 <strong>伐木工 (Lumberjack)</strong></td><td>0</td><td><strong>Axe Man</strong>（+25% 斧头挥速+砍树速度）, +2 Axe, +1 Strength</td><td>Axe 武器始终顶级，0 成本福利之王</td></tr><tr><td>🥈 <strong>老兵 (Veteran)</strong></td><td>-8</td><td><strong>Desensitized</strong>（永不恐慌 + 现在也忽略 Discomfort）, +2 Aiming, +2 Reloading</td><td>B42 buff：Discomfort 免疫让重甲角色受益</td></tr><tr><td>🥉 <strong>窃贼 (Burglar)</strong></td><td>-6</td><td><strong>可以 Hotwire 车辆</strong>, +2 Nimble/+2 Sneak/+2 Lightfooted</td><td>Hotwire 仍是游戏中最稀缺的早期能力，Nimble 对战斗机动性极关键</td></tr></tbody></table><h3 id="a-档-—-强力选择" tabindex="-1">A 档 — 强力选择 <a class="header-anchor" href="#a-档-—-强力选择" aria-label="Permalink to &quot;A 档 — 强力选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>B42 适配</th></tr></thead><tbody><tr><td><strong>消防员 (Fire Officer)</strong></td><td>0</td><td>+1 Axe/+1 Fitness/+1 Sprinting/+1 Strength</td><td>全面且 0 成本，开局就是强化版平民</td></tr><tr><td><strong>维修工 (Repairman)</strong></td><td>-4</td><td><strong>+2 Maintenance</strong>, +1 Carpentry, +1 Short Blunt</td><td>Maintenance 在 B42 极度重要——武器寿命+自制物品耐久</td></tr><tr><td><strong>木匠 (Carpenter)</strong></td><td>+2</td><td><strong>+3 Carpentry</strong></td><td>拆解不给木工 XP 后，开局高木工价值飙升</td></tr><tr><td><strong>建筑工 (Construction Worker)</strong></td><td>-2</td><td>+3 Short Blunt, +1 Carpentry</td><td>B42.16 后短棍/长棍技能分开，定位更清晰</td></tr><tr><td><strong>技工 (Mechanic)</strong></td><td>-4</td><td><strong>Amateur Mechanic</strong>, +3 Mechanics, +1 Short Blunt</td><td>车辆仍是生存核心，专业技工价值不减</td></tr></tbody></table><h3 id="b-档-—-可选" tabindex="-1">B 档 — 可选 <a class="header-anchor" href="#b-档-—-可选" aria-label="Permalink to &quot;B 档 — 可选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>说明</th></tr></thead><tbody><tr><td><strong>警察 (Police Officer)</strong></td><td>-4</td><td>+3 Aiming, +1 Nimble, +2 Reloading</td><td>枪械角色，但枪声引怪是硬伤。Nimble 价值高</td></tr><tr><td><strong>保安 (Security Guard)</strong></td><td>-2</td><td><strong>Night Owl</strong>, +1 Lightfooted, +2 Sprinting</td><td>便宜好用，夜猫子适合夜间作业</td></tr><tr><td><strong>公园巡警 (Park Ranger)</strong></td><td>-4</td><td>+1 Axe, +1 Carpentry, +2 Foraging, +2 Trapping</td><td>B42 荒野生存 + 狩猎系统让户外职业更实用</td></tr><tr><td><strong>健身教练 (Fitness Instructor)</strong></td><td>-6</td><td><strong>Nutritionist</strong>, +3 Fitness, +2 Sprinting</td><td>Fitness 对肌肉疲劳系统有直接帮助</td></tr><tr><td><strong>厨师 (Chef)</strong></td><td>-4</td><td><strong>Cook</strong>, +3 Cooking, +1 Maintenance, +1 Short Blade</td><td>B42 烹饪系统重做 + 食物保存 = 厨师价值上升</td></tr><tr><td><strong>汉堡工 (Burger Flipper)</strong></td><td>+2</td><td><strong>Cook</strong>, +2 Cooking, +1 Maintenance, +1 Short Blade</td><td>最便宜获得 Maintenance 的方式（反赚 2 点），性价比之王</td></tr><tr><td><strong>电工 (Electrician)</strong></td><td>-4</td><td>+3 Electrical</td><td>发电机能力，但杂志也能解决</td></tr><tr><td><strong>工程师 (Engineer)</strong></td><td>-4</td><td>+1 Carpentry, +1 Electrical</td><td>配方独特（炸弹/陷阱），娱乐性大于实用</td></tr></tbody></table><h3 id="c-档-—-不推荐-除非-rp" tabindex="-1">C 档 — 不推荐（除非 RP） <a class="header-anchor" href="#c-档-—-不推荐-除非-rp" aria-label="Permalink to &quot;C 档 — 不推荐（除非 RP）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>原因</th></tr></thead><tbody><tr><td><strong>医生 (Doctor)</strong></td><td>+2</td><td>First Aid 是游戏中最没用的技能——被咬了 100% 死，小伤随便处理</td></tr><tr><td><strong>护士 (Nurse)</strong></td><td>+2</td><td>First Aid + Lightfooted + 内置 Night Owl。比医生好一点但仍然一般</td></tr><tr><td><strong>农夫 (Farmer)</strong></td><td>+2</td><td>Farming 是最容易练的技能之一，不值得用职业点</td></tr><tr><td><strong>渔夫 (Fisherman)</strong></td><td>-2</td><td>Fishing 重做后更互动，但技能本身容易练，不必占职业位</td></tr><tr><td><strong>金属工 (Metalworker)</strong></td><td>-6</td><td>锻造线需要大量前置投入，开局选金属工不如后期转职</td></tr></tbody></table><h3 id="特殊-—-自定义" tabindex="-1">特殊 — 自定义 <a class="header-anchor" href="#特殊-—-自定义" aria-label="Permalink to &quot;特殊 — 自定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>说明</th></tr></thead><tbody><tr><td><strong>失业 (Unemployed)</strong></td><td>+8</td><td>8 点自由分配，配合版本最强负面特征可凑出暴力开局</td></tr></tbody></table><hr><h2 id="b42-职业选择策略" tabindex="-1">B42 职业选择策略 <a class="header-anchor" href="#b42-职业选择策略" aria-label="Permalink to &quot;B42 职业选择策略&quot;">​</a></h2><h3 id="b42-的环境变化对职业的影响" tabindex="-1">B42 的环境变化对职业的影响 <a class="header-anchor" href="#b42-的环境变化对职业的影响" aria-label="Permalink to &quot;B42 的环境变化对职业的影响&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>肌肉疲劳 → 轻型武器开局更有吸引力（Security Guard, Burger Flipper）</span></span>
<span class="line"><span>锻造系统 → Maintenance 和 Carpentry 价值大增（Repairman, Carpenter）</span></span>
<span class="line"><span>荒野扩展 → 户外技能不再纯娱乐（Park Ranger）</span></span>
<span class="line"><span>烹饪重做 → 厨师和汉堡工不再是凑数职业</span></span>
<span class="line"><span>光照重做 → Night Owl 从&quot;还行&quot;变&quot;实用&quot;</span></span></code></pre></div><h3 id="推荐开局路线" tabindex="-1">推荐开局路线 <a class="header-anchor" href="#推荐开局路线" aria-label="Permalink to &quot;推荐开局路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>玩法风格</th><th>推荐职业</th><th>搭配</th></tr></thead><tbody><tr><td><strong>新手保险</strong></td><td>Repairman + 正面特征</td><td>Maintenance +2 让武器活更久</td></tr><tr><td><strong>战斗狂</strong></td><td>Lumberjack + 速度特征</td><td>Axe Man + 高体能 = 砍瓜切菜</td></tr><tr><td><strong>枪械流</strong></td><td>Veteran + Target Shooter</td><td>不恐慌不不适，站桩输出</td></tr><tr><td><strong>潜行流</strong></td><td>Burglar + 轻量特征</td><td>Hotwire + 高机动</td></tr><tr><td><strong>锻造流</strong></td><td>Repairman 或 Carpenter</td><td>制作专注，Maintenance/Carpentry 打底</td></tr><tr><td><strong>荒野流</strong></td><td>Park Ranger + 户外特征</td><td>Foraging + Trapping + 新狩猎系统</td></tr></tbody></table><hr><h2 id="特征搭配建议" tabindex="-1">特征搭配建议 <a class="header-anchor" href="#特征搭配建议" aria-label="Permalink to &quot;特征搭配建议&quot;">​</a></h2><h3 id="b42-特别推荐的正向特征" tabindex="-1">B42 特别推荐的正向特征 <a class="header-anchor" href="#b42-特别推荐的正向特征" aria-label="Permalink to &quot;B42 特别推荐的正向特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>理由</th></tr></thead><tbody><tr><td><strong>Tinkerer</strong> (新)</td><td>加 Maintenance——B42 最重要的技能之一</td></tr><tr><td><strong>Brave</strong></td><td>减少恐慌，老兵下位替代</td></tr><tr><td><strong>Stout/Strong</strong></td><td>力量增加负重和伤害，肌肉疲劳下更有价值</td></tr><tr><td><strong>Athletic/Fit</strong></td><td>体能直接影响武器挥舞可持续时间</td></tr><tr><td><strong>Cat&#39;s Eyes</strong></td><td>B42 光照重做后夜视能力价值飞升</td></tr><tr><td><strong>Dextrous</strong></td><td>物资转移加速，永远是好的</td></tr><tr><td><strong>Wakeful</strong></td><td>减少睡眠需求，更多时间干活</td></tr></tbody></table><h3 id="b42-推荐负面特征" tabindex="-1">B42 推荐负面特征 <a class="header-anchor" href="#b42-推荐负面特征" aria-label="Permalink to &quot;B42 推荐负面特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>给点</th><th>B42 还值不值</th></tr></thead><tbody><tr><td><strong>Smoker</strong></td><td>+4</td><td>⚠️ B42 已削弱，不再是&quot;免费点&quot;。但烟草可以自己种了</td></tr><tr><td><strong>High Thirst</strong></td><td>+6</td><td>仍然安全，水源管理不变</td></tr><tr><td><strong>Weak Stomach</strong></td><td>+3</td><td>仍然安全（别吃变质食物就行）</td></tr><tr><td><strong>Short Sighted</strong></td><td>+2</td><td>仍然可用，觅食惩罚可接受</td></tr><tr><td><strong>Slow Healer</strong></td><td>+6</td><td>安全，反正被咬了都是死</td></tr><tr><td><strong>Thin-skinned</strong></td><td>+8</td><td>高风险，被咬=死，但老玩家可控</td></tr><tr><td><strong>Prone to Illness</strong></td><td>+4</td><td>B42 天气更复杂，略增风险</td></tr><tr><td><strong>Slow Reader</strong></td><td>+2</td><td>⚠️ B42 技能书更重要了，不推荐了</td></tr></tbody></table>`,32)])])}const p=r(e,[["render",o]]);export{c as __pageData,p as default};
